mapper.insert:
insert into ai_image_provider(
    provider_code, provider_name, adapter_type, response_mode, supports_batch, base_url, api_key, enabled, sort_order, remark, create_time, update_time
) values (
    #{providerCode}, #{providerName}, #{adapterType}, #{responseMode}, #{supportsBatch}, #{baseUrl}, #{apiKey}, #{enabled}, #{sortOrder}, #{remark}, sysdate(), sysdate()
)

insert into ai_image_provider_model(
    provider_code, model, provider_model, enabled, create_time, update_time
) values (
    #{providerCode}, #{model}, #{providerModel}, #{enabled}, sysdate(), sysdate()
)

insert into ai_image_model_route(
    model, enabled, primary_provider_code, backup_provider_code, fallback_enabled, sort_order, remark, create_time, update_time
) values (
    #{model}, #{enabled}, #{primaryProviderCode}, #{backupProviderCode}, #{fallbackEnabled}, #{sortOrder}, #{remark}, sysdate(), sysdate()
)
